<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Event-Driven Architecture Panorama</title>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root {
  --bg: #0d1117;
  --surface-0: #161b22;
  --surface-1: #1c2330;
  --surface-2: #222b38;
  --border: rgba(139,157,175,0.14);
  --border-bright: rgba(139,157,175,0.28);
  --text: #e2e8f0;
  --text-dim: #8b9db0;
  --text-muted: #556070;

  /* Domain colors */
  --c-order: #e67e2e;
  --c-order-dim: rgba(230,126,46,0.12);
  --c-payment: #3b9eed;
  --c-payment-dim: rgba(59,158,237,0.12);
  --c-inventory: #4aba7a;
  --c-inventory-dim: rgba(74,186,122,0.12);
  --c-shipping: #b07de8;
  --c-shipping-dim: rgba(176,125,232,0.12);
  --c-notification: #e8c84a;
  --c-notification-dim: rgba(232,200,74,0.12);
  --c-analytics: #e8724a;
  --c-analytics-dim: rgba(232,114,74,0.12);
  --c-kafka: #1f6b3e;
  --c-kafka-bg: rgba(31,107,62,0.18);
  --c-schema: #c0986a;
  --c-schema-dim: rgba(192,152,106,0.12);
  --c-dlq: #c0394b;
  --c-dlq-dim: rgba(192,57,75,0.15);
  --c-monitor: #556ba8;
  --c-monitor-dim: rgba(85,107,168,0.15);

  --font-body: 'IBM Plex Sans', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
  --radius: 6px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 13px;
  line-height: 1.5;
  min-height: 100vh;
}

/* Background grid */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(rgba(139,157,175,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(139,157,175,0.03) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
  z-index: 0;
}

.page {
  position: relative;
  z-index: 1;
  max-width: 1440px;
  margin: 0 auto;
  padding: 28px 32px 48px;
}

/* ── Header ── */
.header {
  margin-bottom: 24px;
  border-bottom: 1px solid var(--border);
  padding-bottom: 18px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
.header-left {}
.header-label {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 6px;
}
.header h1 {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text);
}
.header-sub {
  font-size: 12px;
  color: var(--text-dim);
  margin-top: 4px;
}
.header-stats {
  display: flex;
  gap: 20px;
  flex-shrink: 0;
  align-items: center;
}
.stat-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.stat-num {
  font-family: var(--font-mono);
  font-size: 18px;
  font-weight: 500;
  color: var(--text);
}
.stat-lbl {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* ── Legend ── */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 22px;
  margin-bottom: 20px;
  padding: 10px 14px;
  background: var(--surface-0);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.legend-section {
  display: flex;
  align-items: center;
  gap: 16px;
}
.legend-sep {
  width: 1px;
  height: 20px;
  background: var(--border);
  flex-shrink: 0;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text-dim);
  white-space: nowrap;
}
.leg-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.leg-line {
  width: 24px;
  height: 2px;
  flex-shrink: 0;
}
.leg-line.dashed {
  background: repeating-linear-gradient(90deg,
    currentColor 0, currentColor 4px,
    transparent 4px, transparent 8px);
}

/* ── Main diagram grid ── */
.diagram-grid {
  display: grid;
  grid-template-columns: 200px 1fr 200px;
  grid-template-rows: auto auto auto auto;
  gap: 0;
}

/* ── Sections ── */
.section-label {
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.section-label::before {
  content: '';
  display: block;
  width: 14px;
  height: 1px;
  background: currentColor;
}

/* ── Service cards ── */
.svc-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 12px;
  background: var(--surface-1);
  position: relative;
  transition: border-color 0.15s;
}
.svc-card:hover { border-color: var(--border-bright); }
.svc-card-name {
  font-size: 11.5px;
  font-weight: 600;
  margin-bottom: 3px;
}
.svc-card-domain {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 6px;
}
.role-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 8.5px;
  padding: 1px 5px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}
.svc-topics {
  font-size: 10px;
  color: var(--text-dim);
  line-height: 1.7;
}
.svc-topics code {
  font-family: var(--font-mono);
  font-size: 9px;
  padding: 0 3px;
  background: rgba(255,255,255,0.05);
  border-radius: 2px;
}
.svc-retry {
  margin-top: 5px;
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-muted);
  padding: 2px 5px;
  border-radius: 3px;
  background: rgba(255,255,255,0.04);
  display: inline-block;
}
.svc-alert {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-muted);
  margin-top: 3px;
}

/* ── Kafka hub ── */
.kafka-hub {
  background: var(--c-kafka-bg);
  border: 1px solid rgba(31,107,62,0.5);
  border-radius: 8px;
  padding: 16px;
}
.kafka-hub-title {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  color: #4aba7a;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.kafka-hub-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(74,186,122,0.25);
}
.topic-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.topic-card {
  border-radius: 5px;
  padding: 8px 10px;
  border: 1px solid rgba(255,255,255,0.07);
  position: relative;
  overflow: hidden;
}
.topic-card::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  border-radius: 3px 0 0 3px;
}
.topic-name {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  margin-bottom: 4px;
  line-height: 1.3;
}
.topic-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 3px 6px;
}
.topic-badge {
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--text-muted);
  padding: 1px 4px;
  border-radius: 2px;
  background: rgba(255,255,255,0.05);
}
.topic-tput {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--text-dim);
  margin-top: 4px;
}

/* Category colors */
.cat-order { background: var(--c-order-dim); }
.cat-order .topic-card::before, .cat-order::before { background: var(--c-order); }
.cat-payment { background: var(--c-payment-dim); }
.cat-payment::before { background: var(--c-payment); }
.cat-inventory { background: var(--c-inventory-dim); }
.cat-inventory::before { background: var(--c-inventory); }
.cat-shipping { background: var(--c-shipping-dim); }
.cat-shipping::before { background: var(--c-shipping); }
.cat-dlq { background: var(--c-dlq-dim); }
.cat-dlq::before { background: var(--c-dlq); }

/* ── Schema registry ── */
.schema-box {
  border: 1px solid rgba(192,152,106,0.4);
  background: var(--c-schema-dim);
  border-radius: var(--radius);
  padding: 12px 14px;
}
.schema-title {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  color: var(--c-schema);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 8px;
}
.schema-item {
  font-size: 10px;
  color: var(--text-dim);
  margin-bottom: 3px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.schema-item code {
  font-family: var(--font-mono);
  font-size: 9px;
  color: var(--c-schema);
  opacity: 0.8;
}
.schema-dot {
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--c-schema);
  flex-shrink: 0;
  opacity: 0.7;
}

/* ── DLQ section ── */
.dlq-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.dlq-card {
  border: 1px dashed rgba(192,57,75,0.45);
  background: var(--c-dlq-dim);
  border-radius: 5px;
  padding: 8px 10px;
}
.dlq-name {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 500;
  color: #e05570;
  margin-bottom: 3px;
}
.dlq-meta {
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--text-muted);
  line-height: 1.7;
}
.dlq-retention {
  color: #e05570;
  opacity: 0.8;
}

/* ── Retry table ── */
.retry-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
}
.retry-table th {
  font-family: var(--font-mono);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  text-align: left;
  padding: 5px 8px;
  border-bottom: 1px solid var(--border);
  font-weight: 400;
}
.retry-table td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.retry-table tr:last-child td { border-bottom: none; }
.retry-table tr:hover td { background: rgba(255,255,255,0.02); }
.strategy-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 8.5px;
  padding: 2px 6px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.strat-exp {
  background: rgba(59,158,237,0.12);
  color: #3b9eed;
  border: 1px solid rgba(59,158,237,0.25);
}
.strat-fixed {
  background: rgba(74,186,122,0.12);
  color: #4aba7a;
  border: 1px solid rgba(74,186,122,0.25);
}
.strat-none {
  background: rgba(139,157,175,0.08);
  color: var(--text-muted);
  border: 1px solid var(--border);
}
.jitter-yes { color: #4aba7a; }
.jitter-no { color: var(--text-muted); }

/* ── Monitoring chain ── */
.monitor-chain {
  display: flex;
  align-items: stretch;
  gap: 0;
  overflow-x: auto;
}
.mon-stage {
  flex: 1;
  min-width: 120px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 12px;
  background: var(--surface-1);
  position: relative;
}
.mon-stage + .mon-stage {
  border-left: none;
  border-radius: 0 var(--radius) var(--radius) 0;
}
.mon-stage:first-child {
  border-radius: var(--radius) 0 0 var(--radius);
}
.mon-arrow {
  display: flex;
  align-items: center;
  color: var(--text-muted);
  font-size: 14px;
  padding: 0 4px;
  flex-shrink: 0;
}
.mon-title {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}
.mon-items {
  list-style: none;
}
.mon-item {
  font-size: 9.5px;
  color: var(--text-dim);
  margin-bottom: 2px;
  display: flex;
  align-items: flex-start;
  gap: 5px;
  line-height: 1.4;
}
.mon-item::before {
  content: '·';
  color: var(--text-muted);
  flex-shrink: 0;
  margin-top: 0;
}

/* ── Flow arrows SVG overlay ── */
.flow-diagram {
  position: relative;
}

/* ── Structured layout panels ── */
.panel {
  background: var(--surface-0);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.panel-title {
  font-family: var(--font-mono);
  font-size: 9.5px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.panel-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ── Full architecture SVG flow ── */
.arch-container {
  position: relative;
  width: 100%;
}

/* ── Main layout sections ── */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.row-producers {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.row-kafka {
  position: relative;
}

.row-consumers {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.row-support {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.row-dlq {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.row-monitoring {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

/* Color-coded left border on service cards */
.svc-order { border-left: 3px solid var(--c-order); }
.svc-payment { border-left: 3px solid var(--c-payment); }
.svc-inventory { border-left: 3px solid var(--c-inventory); }
.svc-shipping { border-left: 3px solid var(--c-shipping); }
.svc-notification { border-left: 3px solid var(--c-notification); }
.svc-analytics { border-left: 3px solid var(--c-analytics); }

.role-producer { background: rgba(230,126,46,0.12); color: var(--c-order); border: 1px solid rgba(230,126,46,0.25); }
.role-consumer { background: rgba(59,158,237,0.12); color: var(--c-payment); border: 1px solid rgba(59,158,237,0.25); }
.role-both { background: rgba(74,186,122,0.12); color: var(--c-inventory); border: 1px solid rgba(74,186,122,0.25); }

/* Section connectors row */
.connector-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 4px 0;
  position: relative;
}
.connector-row svg {
  width: 100%;
  height: 36px;
}

/* Arrow colors */
.arrow-happy { stroke: rgba(74,186,122,0.55); }
.arrow-dlq { stroke: rgba(192,57,75,0.7); stroke-dasharray: 5 4; }
.arrow-schema { stroke: rgba(192,152,106,0.6); stroke-dasharray: 3 3; }
.arrow-monitor { stroke: rgba(85,107,168,0.5); stroke-dasharray: 2 3; }

/* Two column layout for bottom sections */
.bottom-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

/* Chip for topic category */
.cat-chip {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 8px;
  padding: 1px 5px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-right: 4px;
}

/* Throughput bar mini chart */
.tput-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}
.tput-bar-track {
  flex: 1;
  height: 3px;
  background: rgba(255,255,255,0.08);
  border-radius: 2px;
  overflow: hidden;
}
.tput-bar-fill {
  height: 100%;
  border-radius: 2px;
}
.tput-val {
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--text-muted);
  white-space: nowrap;
  min-width: 54px;
  text-align: right;
}

/* Fade-in animation */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.fade-in { animation: fadeUp 0.35s ease both; }
.fade-in:nth-child(1) { animation-delay: 0.05s; }
.fade-in:nth-child(2) { animation-delay: 0.10s; }
.fade-in:nth-child(3) { animation-delay: 0.15s; }
.fade-in:nth-child(4) { animation-delay: 0.20s; }
.fade-in:nth-child(5) { animation-delay: 0.25s; }
.fade-in:nth-child(6) { animation-delay: 0.30s; }
@media (prefers-reduced-motion: reduce) {
  .fade-in { animation: none; }
}

/* Flow type legend lines */
.flow-happy { color: #4aba7a; }
.flow-error { color: #e05570; }
.flow-schema { color: var(--c-schema); }
.flow-monitor { color: #6a82c8; }
</style>
</head>
<body>
<div class="page">

<!-- ── Header ── -->
<header class="header">
  <div class="header-left">
    <div class="header-label">Architecture Diagram · Event-Driven System</div>
    <h1>Kafka Event-Driven Architecture Panorama</h1>
    <div class="header-sub">6 microservices · 11 topics (7 business + 4 DLQ) · 33 event flows · Avro/Schema Registry · Prometheus observability</div>
  </div>
  <div class="header-stats">
    <div class="stat-chip">
      <span class="stat-num">6</span>
      <span class="stat-lbl">Services</span>
